import sys

def max_count_01(S):
    n = len(S)
    count_0 = count_1 = 0
    for i in range(n):
        if S[i] == '0':
            count_0 += 1
        else:
            count_1 += 1

    # The maximum number of '01' substrings is the minimum of the number of '0's and '1's
    return min(count_0, count_1)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    T = int(data[index])
    index += 1
    results = []

    for _ in range(T):
        N = int(data[index])
